    [2231]={name="Inferno Robe",quality=2,ilvl=40,reqLevel=35,sourceType="quest_reward",instructions="Reward from the quest 'WANTED: Baron Vardus'.",zone="Hillsbrad Foothills",questName="WANTED: Baron Vardus",lore="By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate."},
