    [10627]={name="Bludgeon of the Grinning Dog",quality=3,ilvl=47,reqLevel=42,sourceType="world_drop",instructions="World drop around level 45-50.",proc="Chance on hit: Bludgeon the target, dealing 126 Physical damage. Canines and Hyaenidae are stunned and sit for 3 sec."},
