    [11784]={name="Arbiter's Blade",quality=3,ilvl=53,reqLevel=48,sourceType="boss_drop",instructions="Drops from Warder Stilgiss.",zone="Blackrock Depths",npc="Warder Stilgiss",proc="Equip: Improves your chance to hit by 0.7%."},
