    [19972]={name="Lucky Fishing Hat",quality=2,ilvl=40,sourceType="quest_reward",instructions="Reward from the quest 'Rare Fish - Keefer's Angelfish'. Starts with Fishbot 5000 in Stranglethorn Vale. Objective: Progress*Whir* *Click* &nbsp;I seek rare fish for Fishmaster Bluegill to catalogue. &nbsp; If you bring me a Keefer's Angelfish, I will provide you with this fine reward. *Zzzap* *Whir*.",zone="Stranglethorn Vale",questName="Rare Fish - Keefer's Angelfish",reqSkills={{"Fishing",1}}},
    [20035]={name="Glacial Spike",quality=3,ilvl=52,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'Destroy Morphaz'. Pick it over the other reward choices.",questName="Destroy Morphaz",lore="There is a green drake deep in the sunken temple of Atal'Hakkar by the name of Morphaz. Years ago, he overwhelmed me in a bold ambush and consumed my apprentice whole.",proc="Equip: Your Frostbolt spells have a 6% chance to restore 50 mana when cast."},
    [20037]={name="Arcane Crystal Pendant",quality=3,ilvl=52,reqLevel=50,sourceType="quest_reward",instructions="Reward from the quest 'Destroy Morphaz'. Pick it over the other reward choices.",questName="Destroy Morphaz",lore="Years ago, he overwhelmed me in a bold ambush and consumed my apprentice whole. While the loss of an apprentice is not unknown to me, this particular one carried an arcane shard of unsurpassed size and quality."},
